def solve(I, cond_c=None):
    H=len(I); W=len(I[0])
    bg=collections.Counter(x for r_ in I for x in r_).most_common(1)[0][0]
    seeds=[(i,j,I[i][j]) for i in range(H) for j in range(W) if I[i][j]!=bg]
    out=[r[:] for r in I]
    fam=lines_by_seed(seeds)
    for (c,f),sl in fam.items():
        sl.sort(key=lambda p:(p[0],p[1]))
        if len(sl)<2:
            # lonely seed: paint full line only if condition holds
            if cond_c and cond_c(sl):
                for i,j in sl:
                    for t in range(-max(H,W),max(H,W)+1):
                        q=(i+t,j+t) if f=='main' else (i+t,j-t)
                        if 0<=q[0]<H and 0<=q[1]<W and out[q[0]][q[1]]==bg:
                            out[q[0]][q[1]]=c
            continue
        # pair-fill: consecutive seeds on same line, color of first seed in scan order
        for a,b in zip(sl,sl[1:]):
            d=max(abs(a[0]-b[0]),abs(a[1]-b[1]))
            if d<2: continue
            ca,cb=a[0]-a[1],b[0]-b[1]
            sa,sb=a[0]+a[1],b[0]+b[1]
            step = (1,1) if f=='main' else (1,-1)
            # cells strictly between, painted from each endpoint up to floor(d/2)
            for sgn in (1,-1):
                cnt=d//2
                for k in range(1,cnt+1):
                    q=(a[0]+sgn*k*step[0], a[1]+sgn*k*step[1])
                    if 0<=q[0]<H and 0<=q[1]<W and out[q[0]][q[1]]==bg:
                        out[q[0]][q[1]]=sl[0][2]
    return out

