import collections
def solve(g):
    h,w=len(g),len(g[0])
    cnt=collections.Counter(x for r_ in g for x in r_)
    bg=cnt.most_common(1)[0][0]
    out=[r_[:] for r_ in g]
    pts=collections.defaultdict(list)
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg: pts[g[i][j]].append((i,j))
    ones=set(pts[1])
    mains=collections.defaultdict(list); antis=collections.defaultdict(list)
    for i,j in ones: mains[i-j].append((i,j)); antis[i+j].append((i,j))
    # 1s: full line fill (both directions) on any diagonal containing>=2 ones, over bg only
    def fl(v,color):
        v=sorted(v)
        for k in range(len(v)-1):
            (i0,j0),(i1,j1)=v[k],v[k+1]
            s=(i1>i0)-(i1<i0); tj=(j1>j0)-(j1<j0)
            for t in range(abs(i1-i0)+1):
                a=i0+s*t; b=j0+tj*t
                if g[a][b]==bg: out[a][b]=color
    for v in mains.values():
        if len(v)>=2: fl(v,1)
    for v in antis.values():
        if len(v)>=2: fl(v,1)
    # 6s: collinear with >=2 ones paints ONLY the perpendicular diagonal fully both ways
    for si,sj in pts[6]:
        coll_main = (si-sj) in {i-j for i,j in ones} and len(mains[si-sj])>=2
        coll_anti = (si+sj) in {i+j for i,j in ones} and len(antis[si+sj])>=2
        if coll_main: d2=(1,-1)          # main diag collinear -> paint anti-diag fully
        elif coll_anti: d2=(1,1)          # anti diag collinear -> paint main diag fully
        else: continue
        di,dj=d2
        for k in range(-max(h,w),max(h,w)+1):
            a,b=si+di*k,sj+dj*k
            if 0<=a<h and 0<=b<w and g[a][b]==bg: out[a][b]=6
    return out
for n in [1,2,3,4,5]:
    print(n, solve(G[f'Demo pair {n} input'])==G[f'Demo pair {n} output'])

